SELECT sname, ROUND(AVG(AvgScrMath)) AS avg_math, COUNT(*) AS n
FROM satscores WHERE rtype='S'
GROUP BY sname ORDER BY avg_math DESC LIMIT 9;

SELECT s.School AS school_name, s.MailStreet AS postal_street
FROM satscores AS t JOIN schools AS s ON s.CDSCode = t.cds
ORDER BY t.AvgScrMath DESC LIMIT 1 OFFSET 6;
